items.raw:
\noindent This section is devoted to proving Theorem $\ref{thm1}.$ Our argument is started with Guerra's replica symmetry breaking interpolation scheme in the spherical models (see Section 3 in \cite{Tal061}). In the case when $p$-spin interactions for odd $p\geq 3$ are not present in $(\ref{eq2})$, this scheme implies that the upper limit of the free energy is bounded from above by $\inf_{\vec{x}}\mathcal{P}(\vec{x}).$ The fact that this bound still holds in the general mixed $p$-spin case relies on Talagrand's positivity principle on the overlap (see \cite{Tal03} and Section 12.3 in \cite{Tal11}) that is deduced from the validity of the G.G. identities \cite{GG98} derived by a perturbation trick on the Hamiltonian. This part of the argument is well-known and has been used in several places. For example, the readers are referred to Theorem 14.4.4 \cite{Tal11} for a great detailed discussion.

Our main concern in the proof will be concentrated on obtaining the lower bound, that is, the lower limit of the free energy is bounded from below by
$\inf_{\vec{x}}\mathcal{P}(\vec{x})$, that will be established in several steps and is based on the A.S.S. scheme. Again due to the non-product structure of the uniform measure on the sphere, additional technical issues occur. For instance, in the Ising spin glass model, the argument for the lower bound only uses the A.S.S. scheme with a single cavity coordinate, that is $M=1$ (see Theorem 3.5 \cite{AC10}, Lemma 11 \cite{Pan10:2}, or Proposition 2 \cite{Pan11:1}), but this is not the case in our model. Indeed, recalling the formulation of the Parisi formula in the spherical model, one may figure out immediately that it is necessary to deal with the A.S.S. scheme $(\ref{ASS:prop1:eq1})$ with all $M\geq 1$ and compute their lower limit in $M.$ Under this circumstance, we find the fact that the Parisi functionals $(\mathcal{P}_M)_{M\geq 1}$ have the same Lipschitz constant with respect to the $L_1$-norm as stated in Lemma $\ref{AGM:prop21}$ below is of great use. 
\smallskip

\noindent{\bf The A.S.S. scheme for the perturbed Hamiltonian.} For each $u=(u_p)_{p\geq 1}$ with $1\leq u_p\leq 2,$ let us consider a perturbation Hamiltonian 
\begin{align*}

H_{N}^{pert}({\vec{\sigma}})=\frac{1}{N^{1/8}}\sum_{p\geq 1}\frac{u_p}{2^p}H_{N,p}'({\vec{\sigma}}),
\end{align*}
where $H_{N,p}'({\vec{\sigma}})$ are independent copies of the $p$-spin Hamiltonian in $(\ref{eq1})$. Since the perturbation term is of a small order, replacing $H_N$ with $H_N+H_N^{pert}$ in $(\ref{thm1:eq1})$ obviously does not affect the limit and in addition, the following A.S.S. scheme also holds. 
Consider another perturbation Hamiltonian
\begin{align*}

H_{M,N}^{pert}({\vec{\sigma}})=\frac{1}{(M+N)^{1/8}}\sum_{p\geq 1}\frac{u_p}{2^p}\left(\frac{N}{M+N}\right)^{(p-1)/2}H_{N,p}'({\vec{\sigma}}).
\end{align*}
Let $G_{M,N}^-$ be the Gibbs measure corresponding to the Hamiltonian $H_{M,N}+H_{M,N}^{pert}$ with reference measure $\lambda_N$ and $\left<\cdot\right>_{M,N}^-$ be the average with respect to the product Gibbs measure $G_{M,N}^{-\otimes\infty}.$

\begin{proposition}[The A.S.S. scheme]\label{ASS:cor} Recall $A_\delta$ and $\nu_M$ from Theorem $\ref{ASS:prop1}.$
For every $\delta>0$ and $M\geq 1,$ we have
\begin{align}
\begin{split}\label{ASS:cor:eq1}
&\liminf_{N\rightarrow\infty}\frac{1}{N}\mathbb{E}\log Z_N\\
&\geq\frac{1}{M}\liminf_{N\rightarrow\infty}\sup_{u}\left(\mathbb{E}\log \int_{S_M}\left<\exp \vec{\varepsilon}\cdot \vec{z} ({\vec{\sigma}})\right>_{M,N}^-d\lambda_M(\vec{\varepsilon})-
\mathbb{E}\log \left<\exp \sqrt{M}y({\vec{\sigma}})\right>_{M,N}^-\right)\\
&\qquad\qquad -\delta\xi'(1)+\frac{1}{M}\log \nu_M(A_\delta),
\end{split}
\end{align}
where the supremum is taken over all $u=(u_{p})_{p\geq 1}$ with $1\leq u_p\leq 2.$
\end{proposition}

\smallskip

\noindent Starting with the Hamiltonian $H_{M+N}+H_{M+N}^{pert}$ and using the fact that $H_{M+N}^{pert}$ is of a small order, one may easily find that the same arguments in the proof of Theorem $\ref{ASS:prop1}$ also work in Proposition $\ref{ASS:cor}$, so we will leave this part of the proof to the readers. In what follows, for each $M\geq 1$, we will construct a sequence $(u^{M,N})_{N\geq 1}$ for $u^{M,N}=(u_p^{M,N})_{p\geq 1}$ with $1\leq u_p^{M,N}\leq 2$ along which the G.G. identities for the Gibbs measure $G_{M,N}^-$ and the A.S.S. scheme for the Hamiltonian $H_{M,N}+H_{M,N}^{pert}$ hold simultaneously. Let $({\vec{\sigma}}^\ell)_{\ell\geq 1}$ be an i.i.d. sample from $G_{M,N}^-$ and let $R^{M,N}=(R_{\ell,\ell'}^{M,N})_{\ell,\ell'\geq 1}$ be the normalized Gram matrix, or matrix of overlaps, of this sample. Let $\mathcal{C}$ be the collection of all $(p,n,f)$ with $p\geq 1,$ $n\geq 2,$ and $f$ being a monomial of $(R_{\ell,\ell'}^{M,N})_{\ell,\ell'\leq n}.$ We define
\begin{align*}
&\Phi_{M,N}(p,n,f)\\
&=\left|\mathbb{E}\left<f(R_{1,n+1}^{M,N})^p\right>_{M,N}^--\frac{1}{n}\mathbb{E}\left<f\right>_{M,N}^-
\mathbb{E}\left<(R_{1,2}^{M,N})^p\right>_{M,N}^--\frac{1}{n}\sum_{\ell=2}^n
\mathbb{E}\left<f(R_{1,\ell}^{M,N})^p\right>_{M,N}^-\right|
\end{align*}
for $(p,n,f)\in \mathcal{C}.$ Then the G.G. identities can be stated as follows (see Theorem 12.3.1 \cite{Tal11}).

\begin{proposition}\label{prop:GG}
For $M\geq 1$, we have 
\begin{align}\label{prop:GG:eq1}
\lim_{N\rightarrow\infty}\mathbb{E}_u\Phi_{M,N}(p,n,f)=0
\end{align}
for all $(p,n,f)\in\mathcal{C},$ where we view $u=(u_p)_{p\geq 1}$ as a sequence of i.i.d. uniform random variables on $\left[1,2\right]$ and $\mathbb{E}_u$ is the expectation with respect to the randomness of $u.$
\end{proposition}
\smallskip

\noindent Since $\mathcal{C}$ is a countable set, we can enumerate it as $\left\{(p_j,n_j,f_j)\right\}_{j\geq 1}.$
Let us define 
\begin{align*}
\Phi_{M,N}(u)&=\sum_{j\geq 1}\frac{1}{2^j}\Phi_{M,N}(p_j,n_j,f_j),\\
\Lambda_{M,N}(u)&=\frac{1}{M}\left(\mathbb{E}\log\int_{S_M}\left<\exp \vec{\varepsilon}\cdot\vec{z}({\vec{\sigma}})\right>_{M,N}^-d\lambda_M(\vec{\varepsilon})
-\mathbb{E}\log \left<\exp \sqrt{M}y({\vec{\sigma}})\right>_{M,N}^-\right).
\end{align*} 
By Chebyshev's inequality, $\mathbb{P}_u(\Phi_{M,N}\leq \eta)\geq 1-\mathbb{E}_u\Phi_{M,N}/\eta$ for every $\eta>0.$ If we pick $\eta=2\mathbb{E}_u\Phi_{M,N},$ it implies that for any $M$ and $N$ we can always find $u^{M,N}=(u_p^{M,N})_{p\geq 1}$ such that 
$\Phi_{M,N}(u^{M,N})\leq 2\mathbb{E}_u\Phi_{M,N}$. Note that using $\Phi_{M,N}(n,p,f)\leq 2$ and the G.G. identities $(\ref{prop:GG:eq1})$ implies $\lim_{N\rightarrow\infty}\mathbb{E}_u\Phi_{M,N}=0.$ Consequently, we have
\begin{align}
\begin{split}\label{AGM:eq2}
\lim_{N\rightarrow\infty}\Phi_{M,N}(u^{M,N})&=0
\end{split}
\end{align}
and from $(\ref{ASS:cor:eq1})$, $\liminf_{N\rightarrow\infty}N^{-1}\mathbb{E}\log Z_N$ is bounded from below by
\begin{align}
\begin{split}\label{AGM:eq2.1}
\liminf_{N\rightarrow\infty}\Lambda_{M,N}(u^{M,N})-\delta\xi'(1)+\frac{1}{M}\log \nu_M(A_\delta).
\end{split}
\end{align} 
In other words, for each $M\geq 1,$ both the G.G. identities and the A.S.S. scheme hold along $(u^{M,N})_{N\geq 1}$.
Let us redefine the Hamiltonian $H_{M,N}^{pert}$ and the Gibbs measure $G_{M,N}^-$ by fixing parameters $u=u^{M,N}.$

\smallskip


\noindent {\bf Asymptotic Gibbs' measures.} Next, we will find a sequence of asymptotic Gibbs' measures that satisfy the G.G. identities and represent the lower limit in $(\ref{AGM:eq2.1})$. For each $M\geq 1,$ let us pick a subsequence $(N_n)$ along which the limits in $(\ref{AGM:eq2})$ and $(\ref{AGM:eq2.1})$ are achieved and the distribution $R^{M,N}$ under $\mathbb{E}G_{M,N}^{-\otimes\infty}$ converges in the sense of convergence of finite dimensional distributions to the distribution of some array $R^M$. To lighten the notation, we assume without loss of generality that the sequence $(N_n)$ coincides with the natural numbers. Under $\mathbb{E}G_{M,N}^{-\otimes\infty}$, the array ${R}^{M,N}$ is weakly exchangeable, that is, 
\begin{align*}

\left(R_{\pi(\ell),\pi(\ell')}^{M,N}\right)\stackrel{d}{=}\left(R_{\ell,\ell'}^{M,N}\right)
\end{align*}
for any permutation $\pi$ of finitely many indices. This property will still be preserved in the limit such that $R^M$ is a weakly exchangable symmetric non-negative definite array. Such an array is called a Gram-de Finetti array and is known to have the Dovbysh-Sudakov representation \cite{DS82}.

\begin{proposition}[The Dovbysh-Sudakov representation]\label{AGM:Prop1}
If $(R_{\ell,\ell'})_{\ell,\ell'\geq 1}$ is a Gram-de Finetti array such that $R_{\ell,\ell}=1$, then there exists a random measure $G$ on the unit ball of a separable Hilbert space such that
\begin{align*}

\left(R_{\ell,\ell'}\right)_{\ell,\ell'\geq 1}\stackrel{d}{=}\left(\vec{\tau}^{\ell}\cdot\vec{\tau}^{\ell'}+\delta_{\ell,\ell'}(1-\|\vec{\tau}^{\ell}\|^2)\right)_{\ell,\ell'\geq 1},
\end{align*}
where $(\vec{\tau}^\ell)$ is an i.i.d. sample from $G.$
\end{proposition}

\smallskip

\noindent Obviously the array $R^M$ satisfies $R_{\ell,\ell}^M=1.$ Using Proposition $\ref{AGM:Prop1}$, let us denote by $G_M$ the random measure generating the array $R^{M}$ and by $(\vec{\tau}^\ell)$ an i.i.d. sample from $G_M$. We also denote by $\left<\cdot\right>_M$ the average with respect to $G_M.$ From $(\ref{AGM:eq2})$ and an approximation argument, the measure $G_M$ satisfies the G.G. identities,
\begin{align}\label{AGM:eq4}
\mathbb{E}\left<f\psi(R_{1,n+1}^M)\right>_M=\frac{1}{n}\mathbb{E}\left<f\right>_M\mathbb{E}\left<\psi(R_{1,2}^M)\right>_M+\frac{1}{n}\sum_{\ell=2}^n
\mathbb{E}\left<f\psi(R_{1,\ell}^M)\right>_M
\end{align}
for all $n\geq 2,$ all bounded measurable function $f$ of $(R_{\ell,\ell'}^M)_{\ell,\ell'\leq n}$, and measurable function $\psi.$
These identities will be used to identify the asymptotic Gibbs measures $G_M$ in next subsection.

Let us continue to check that the limit of $\Lambda_{M,N}(u^{M,N})$ in $N$ can be expressed in terms of $G_{M},$ which relies on the following observation. Suppose for the moment that $R=(R_{\ell,\ell'})_{\ell,\ell'\geq 1}$ is an arbitrary Gram-de Finetti array such that $R_{\ell,\ell}=1.$ Let $\mathcal{L}$ be its distribution  and $G$ be any random measure generating $R$ as Proposition $\ref{AGM:Prop1}.$ Suppose that $\vec{z}(\vec{\tau})=(z_i(\vec{\tau}))_{i\leq M}$ and $y(\vec{\tau})$ are two Gaussian processes on the unit ball of some Hilbert space generating $R$ with covariances
\begin{align*}
\mathbb{E}z_i(\vec{\tau}^1)z_{i'}(\vec{\tau}^2)=\delta_{i,i'}\xi'(\vec{\tau}^1\cdot\vec{\tau}^2),\,\,\mathbb{E}y(\vec{\tau}^1)y(\vec{\tau}^2)=\theta(\vec{\tau}^1\cdot\vec{\tau}^2),
\end{align*}
let $\vec{\eta}$ be a $M$-dimensional standard Gaussian random vector, and let $\eta$ be a standard Gaussian random variable. Denote by $\left<\cdot\right>$ the Gibbs average corresponding to $G$ and define
\begin{align*}
\Psi_M(\mathcal{L})=&\frac{1}{M}\mathbb{E}\log \int_{S_M}\mathbb{E}_{\vec{\eta}}\left<\exp\vec{\varepsilon}\cdot(\vec{z} (\vec{\tau})+\vec{\eta}(\xi'(1)-\xi'(\|\vec{\tau}\|^2))^{1/2})\right>d\lambda_M(\vec{\varepsilon})\\
&-\frac{1}{M}\mathbb{E}\log \mathbb{E}_\eta\left<\exp\sqrt{M}({y}(\vec{\tau})+\eta(\xi'(1)-\xi'(\|\vec{\tau}\|^2))^{1/2})\right>.
\end{align*}

\begin{lemma}\label{AGM:lem2}
For each $M\geq 1,$ $\mathcal{L}\rightarrow \Psi_M(\mathcal{L})$ is a well-defined continuous function with respect to the weak convergence of the distribution $\mathcal{L}.$
\end{lemma}

\smallskip

\noindent This is a generalization of Lemma 3 in \cite{Pan11:1} and can be verified exactly in the same way.  


Let $\mathcal{L}^{M,N}$ and $\mathcal{L}^M$ be the distributions generating $R^{M,N}$ and $R^M$, respectively. 
Then Lemma $\ref{AGM:lem2}$ leads to
\begin{align}\label{AGM:eq8}
\lim_{N\rightarrow\infty}\Lambda_{M,N}(u^{M,N})&=\lim_{N\rightarrow\infty}\Psi_M(\mathcal{L}^{M,N})=\Psi_M(\mathcal{L}^M).
\end{align}




\noindent{\bf Identitying the asymptotic Gibbs' measures using ultrametricity.} Since the asymptotic Gibbs measure $G_M$ satisfies the G.G. identities $(\ref{AGM:eq4})$, the main result in $\cite{Pan11:4}$ implies that the support of $G_M$ is ultrametric with probability one, that is, 
\begin{align*}
\mathbb{E}\left<I(R_{1,2}^M\geq \min(R_{1,3}^M,R_{2,3}^M))\right>_M=1.
\end{align*}
This implies that for any $q$, the inequality $q\leq \vec{\tau}^{\ell}\cdot\vec{\tau}^{\ell'}$ defines an equivalent relation and therefore, the 
array $(I(q\leq R_{\ell,\ell'}^M))_{\ell,\ell'\geq 1}$ is nonnegative definite since it is block-diagonal with blocks consisting of all elements
equal to one. Consider a sequence of functions $(H_k)_{k\geq 1}$ on $\left[0,1\right]$ by defining $H_{k}(q)=j/k$ if $j/(k+1)\leq q<(j+1)/(k+1)$ for $0\leq j\leq k$ and $H_k(1)=1.$ Then we see that $R_{k}^M=(H_k(R_{\ell,\ell'}^M))_{\ell,\ell\geq 1}$ is symmetric, weakly exchangable, and satisfies the G.G. identities. In addition, it is non-negative definite since it can be written as a convex combination of nonnegative definite arrays,
\begin{align*}
H_k(R_{\ell,\ell'}^M)=\sum_{j=1}^{k}\frac{1}{k}I\left(\frac{j}{k+1}\leq R_{\ell,\ell'}^M\right).
\end{align*}
Thus by the Dovbysh-Sudakov representation, $R_{k}^M$ can be generated by a sample from a random measure $G_M^k$ on the unit ball of some Hilbert space.
Since $\sup_{0\leq q\leq 1}|H_k(q)-q|\leq 1/k,$ $(R_k^M)_{k\geq 1}$ converges weakly to $R^M.$ From Lemma $\ref{AGM:lem2},$ we then obtain
\begin{align}\label{AGMU:add1}
\lim_{k\rightarrow\infty}\Psi_M(\mathcal{L}_k^M)=\Psi_M(\mathcal{L}^M),
\end{align}  
where $\mathcal{L}_k^M$ is the distribution for $R_k^M$. On the other hand, from the Baffioni-Rosati theorem \cite{BR00}, an ultrametric measure, such as $G_M^k$, that satisfies the G.G. identities and under which the overlaps $R_k^M$ take finitely many values $(p/k)_{0\leq p\leq k}$ can be identified as the Poisson-Dirichlet cascade with parameters 
\begin{align*}
\mathbf{m}^{M,k}&=(m_p^{M,k})_{0\leq p\leq k}\,\,\mbox{with $m_p^{M,k}=\mathbb{E}\left<I((R_k^M)_{1,2}\leq p/k)\right>_M,$}\\
\mathbf{q}^{M,k}&=(q_p^{M,k})_{0\leq p\leq k+1}\,\,\mbox{with $q_p^{M,k}=p/(k+1)$}.
\end{align*}
For details of this result, one may consult the proof of Theorem 15.3.6 in \cite{Tal11}. Let $\vec{x}_k^M$ be the distribution function corresponding to this triplet $(k,\mathbf{m}^{M,k},\mathbf{q}^{M,k}).$ Using the same argument as Theorem 14.2.1 in \cite{Tal11}, we obtain
\begin{align}\label{AGM:eq6}
\Psi_M(\mathcal{L}_k^M)=\mathcal{P}_M(\vec{x}_k^M).
\end{align}

\begin{lemma} \label{AGM:prop21}
For any two triplets $(k,\mathbf{m},\mathbf{q})$ and $(k',\mathbf{m}',\mathbf{q}')$ associated with the distribution functions $\vec{x}$ and $\vec{x}'$ respectively, we have
\begin{align}
\label{AGM:prop2}
\left|\mathcal{P}_M(\vec{x})-\mathcal{P}_M(\vec{x}')\right|\leq \frac{\xi'(1)}{2}\int_0^1\left|\vec{x}(q)-\vec{x}'(q)\right|dq.
\end{align} 
\end{lemma}

\smallskip

\noindent 
It is well-known that the same Lipschitz property as $(\ref{AGM:prop2})$ for the Parisi functional in the Ising spin glass model was established by F. Guerra \cite{Guerra03}. In the spherical models, despite of the non-product structure on the configuration space, one may find the same approach as Theorem 14.11.2 in \cite{Tal11} can also be applied to obtain $(\ref{AGM:prop2}).$ Let $\mathcal{F}$ be the collection of all distribution functions $\vec{x}$ on $\left[0,1\right]$. Define a metric $d$ on $\mathcal{F}$ by letting $d(\vec{x},\vec{x}')=\int_0^1\left|\vec{x}(q)-\vec{x}'(q)\right|dq$ for every $\vec{x},\vec{x}'\in \mathcal{F}.$ Using the Lipschitz inequality $(\ref{AGM:prop2})$, we can extend the functional $\mathcal{P}_M$ continuously to $\mathcal{F}.$

\smallskip

\noindent{\bf Proof of Theorem \ref{thm1}.} If we denote by $\vec{x}^M$ the distribution of $R_{1,2}^M,$ it follows that by using $(\ref{AGMU:add1})$ and  $(\ref{AGM:eq6})$,
\begin{align}\label{AGM:eq7} 
\Psi_M(\mathcal{L}^M)=\mathcal{P}_M(\vec{x}^M).
\end{align}
From Helly's selection theorem, $(\vec{x}^M)_{M\geq 1}$ contains a weakly convergent subsequence with limit $\vec{x}^\infty.$ For clarity, we simply use $(\vec{x}^M)$ to denote this subsequence. Using $(\ref{AGM:prop2})$ and $(\ref{AGM:eq7})$, if we set $\vec{x}_k^\infty=H_k(\vec{x}^\infty),$ then
\begin{align*}
\limsup_{M\rightarrow\infty}\left|\Psi_M(\mathcal{L}^M)-\mathcal{P}_M(\vec{x}_k^{\infty})\right|
&=\limsup_{M\rightarrow\infty}\left|\mathcal{P}_M(\vec{x}^M)-\mathcal{P}_M(\vec{x}_k^{\infty})\right|\\
&\leq \frac{\xi'(1)}{2}\left(\limsup_{M\rightarrow\infty}d(\vec{x}^M,\vec{x}^{\infty})+d(\vec{x}^\infty,\vec{x}_k^{\infty})\right)\\
&=\frac{\xi'(1)}{2}d(\vec{x}^\infty,\vec{x}_k^{\infty})
\end{align*} 
for every $k\geq 1.$ To sum up, from $(\ref{AGM:eq2.1}),$ $(\ref{AGM:eq8})$, and this inequality, we conclude that 
\begin{align*}
\liminf_{N\rightarrow\infty}\frac{1}{N}\mathbb{E}\log Z_N&\geq \limsup_{M\rightarrow\infty}\left( \Psi_M(\mathcal{L}^M)+\frac{1}{M}\log\nu_M(A_\delta)\right)-\delta\xi'(1)\\
&\geq \limsup_{M\rightarrow\infty}\mathcal{P}_M(\vec{x}_k^\infty)-\limsup_{M\rightarrow\infty}\left|\Psi_M(\mathcal{L}^M)-\mathcal{P}_M(\vec{x}_k^\infty)\right|-\delta\xi'(1)\\
&\geq\inf_{\vec{x}}\mathcal{P}(\vec{x})-\frac{\xi'(1)}{2}d(\vec{x}^\infty,\vec{x}_k^{\infty})-\delta\xi'(1)
\end{align*}
for every $k\geq 1$ and $\delta>0$ and this completes our proof by letting $\delta\rightarrow 0$ and $k\rightarrow\infty.$\qed

