\noindent{\bf Proof of Theorem \ref{ASS:prop1}.}
From $(\ref{ASS:main:eq0})$, $(\ref{ASS:main:eq1})$, and $(\ref{sec2:eq1}),$ using Lemmas  $\ref{ASS:lem4},$ $\ref{ASS:lem2}$, and $\ref{ASS:lem3},$ the lower limit of 
$N^{-1}{\mathbb{E}\log Z_{N}}$ is bounded from below by
\begin{align*}
\frac{1}{M}\liminf_{N\rightarrow\infty}\left(\mathbb{E}\log\int_{A_\delta}\left<\exp \vec{\varepsilon}\cdot\vec{z}({\vec{\sigma}})\right>_{M,N}d\nu_M(\vec{\varepsilon})-\mathbb{E}\log \left<\exp\sqrt{M}y({\vec{\sigma}})\right>_{M,N}\right)-\delta\xi'(1)
\end{align*}
and then  $(\ref{ASS:lem5.1:eq1})$ yields $(\ref{ASS:prop1:eq1}).$\qed

\smallskip

\noindent 
Note that a standard large deviation result yields $\lim_{M\rightarrow \infty}M^{-1}\log\nu_M(A_\delta)=0$ for every $\delta>0.$ Thus $(\ref{ASS:prop1:eq1})$ gives a lower bound for the lower limit of the free energy that will play an essential role in proving the Parisi formula in Section $\ref{proof}.$ Suppose that $\mu_N$ is the uniform probability measure on $\Sigma_N=\left\{-1,+1\right\}^N$. If we replace the measure space $(S_N,\lambda_N)$ by $(\Sigma_N,\mu_N)$ and ignore the error term $-\delta\xi'(1)+M^{-1}\log \nu_M(A_\delta)$ in $(\ref{ASS:prop1:eq1})$, then Theorem \ref{ASS:prop1} gives the A.S.S. scheme for the Ising spin glass model with general mixed $p$-spin interactions (see e.g. Section 15.8 \cite{Tal11}). 

We will take the spirit in \cite{ASS03} to establish the A.S.S. scheme. However, since uniform measure on the spherical configuration space in the spherical models is not a product measure, we have to seek a proper way to approximate this measure by another one that possesses a certain product structure. To deal with this obstacle, we will use the idea of Poincar\'{e}'s lemma (see page 77 \cite{ST93}) that the projection on any fixed $M$ coordinates of the uniform probability measure $\lambda_{M+N}$ on the sphere $S_{M+N}$ converge weakly to $M$-dimensional standard Gaussian measure as $N$ tends to infinity. The argument of our proof proceeds as follows. Recall the definition of $H_{M+N}$ from $(\ref{eq2})$. For ${\vec{\rho}}\in S_{M+N},$ let us write ${\vec{\rho}}=({\vec{\sigma}},\vec{\varepsilon})$ for the first $N$ coordinates ${\vec{\sigma}}=(\sigma_1,\ldots,\sigma_N)$ and the last $M$ cavity coordinates $\vec{\varepsilon}=(\varepsilon_1,\ldots,\varepsilon_M)$ and write
\begin{align*}
H_{M+N}({\vec{\rho}})&=H_{M,N}({\vec{\sigma}})+\sum_{i\leq M}\varepsilon_i Z_i({\vec{\sigma}})+\gamma({\vec{\rho}}),
\end{align*}
where $H_{M,N}$ is given in $(\ref{ASS:eq1}),$ the term $\varepsilon_iZ_i({\vec{\sigma}})$ consists of all terms in $H_{M+N}$ with only one factor $\varepsilon_i$ from $\vec{\varepsilon}$ present, and the last term is the sum of terms with at least two factors in $\vec{\varepsilon}.$ From now on, without causing any ambiguity, for any given vectors $\vec{\omega},\vec{\omega}'\in\Bbb{R}^K$ for some $K\geq 1$, we define $R(\vec{\omega},\vec{\omega}')=K^{-1}\sum_{i\leq K}\omega_i\omega_i'.$ One can check easily that
\begin{align}
\begin{split}
\label{ASS:eq2.1}
\mathbb{E}H_{M,N}({\vec{\sigma}}^1)H_{M,N}({\vec{\sigma}}^2)&=(M+N)\xi\left(\frac{N}{M+N}R({\vec{\sigma}}^1,{\vec{\sigma}}^2)\right),
\end{split}\\
\begin{split}
\label{ASS:eq2.2}
\mathbb{E}Z_i({\vec{\sigma}}^1)Z_i({\vec{\sigma}}^2)&=\xi'\left(\frac{N}{M+N}R({\vec{\sigma}}^1,{\vec{\sigma}}^2)\right),
\end{split}\\
\begin{split}
\label{ASS:eq2.3}
\mathbb{E}\gamma({\vec{\rho}})^2&\leq \frac{M^2}{M+N}\xi''(1).
\end{split}
\end{align}
Let us notice an elementary fact that for a real-valued sequence $(c_N)$, if $\liminf_{N\rightarrow\infty}c_N/N=r\in\mathbb{R},$ then $M^{-1}\liminf_{N\rightarrow\infty}(c_{M+N}-c_N)\leq r$ for every $M\geq 1.$ This implies 
\begin{align}\label{ASS:main:eq0}
&\liminf_{N\rightarrow\infty}\frac{\mathbb{E}\log Z_N}{N}\geq\frac{1}{M}\liminf_{N\rightarrow\infty}\mathbb{E}\log \frac{Z_{M+N}}{Z_N}
\end{align}
and thus to obtain Theorem $\ref{ASS:prop1}$, it suffices to prove that $(\ref{ASS:prop1:eq1})$ is the lower bound of the right-hand side of $(\ref{ASS:main:eq0})$.
Let us write $\mathbb{E}\log{Z_{M+N}}/{Z_N}$ as
\begin{align}
\begin{split}\label{ASS:main:eq1}
&\mathbb{E}\log \int_{A_\delta}\left< \exp\vec{\varepsilon}\cdot \vec{z}({\vec{\sigma}})\right>_{M,N}d\nu_M(\vec{\varepsilon})-\mathbb{E}\log\frac{\int_{S_N}\exp H_Nd\lambda_N({\vec{\sigma}})}{\int_{S_N}\exp H_{M,N}d\lambda_N({\vec{\sigma}})}\\
&+\mathbb{E}\log\frac{Z_{M+N}}{\int_{A_\delta}J_{M,N}d\nu_M(\vec{\varepsilon})},
\end{split}
\end{align}
where  
\begin{align*}
J_{M,N}(\vec{\varepsilon})&=\int_{S_N}\exp(H_{M,N}({\vec{\sigma}})+\vec{\varepsilon}\cdot \vec{z} ({\vec{\sigma}}))d\lambda_N({\vec{\sigma}}),\quad\vec{\varepsilon}\in\mathbb{R}^M.
\end{align*}
In what follows, we prove several lemmas that will be used to bound these three terms in $(\ref{ASS:main:eq1})$ as $N$ tends to infinity.

\begin{proof}
Using the rotational invariance of $\nu_M,$ there  exists a probability measure $\gamma_M$ on $\mathbb{R}^+$ such that
$\nu_M$ is the image of $\gamma_M\times \lambda_M$ under the map $(s,\vec{\varepsilon})
\mapsto s\vec{\varepsilon}.$ For $1\leq s\leq (1+\delta)^{1/2}$, using symmetry,
\begin{align*}
\int \exp s\vec{\varepsilon}\cdot\vec{z} d\lambda_M(\vec{\varepsilon})&=\int \cosh(s\vec{\varepsilon}\cdot\vec{z})d\lambda_M(\vec{\varepsilon})\\
&\geq \int \cosh(\vec{\varepsilon}\cdot\vec{z})d\lambda_M(\vec{\varepsilon})=\int \exp \vec{\varepsilon}\cdot\vec{z} d\lambda_M(\vec{\varepsilon}).
\end{align*} 
Therefore, $(\ref{ASS:lem5:eq1})$ holds by
\begin{align*}
\int_{A_\delta}\exp \vec{\varepsilon}\cdot\vec{z} d\nu_M(\vec{\varepsilon})&=\int_{1}^{(1+\delta)^{1/2}}\int_{S_M}\exp s\vec{\varepsilon}\cdot \vec{z} d\lambda_M(\vec{\varepsilon})d\gamma_M(s)\\
&\geq\int_{1}^{(1+\delta)^{1/2}}\int_{S_M}\exp\vec{\varepsilon}\cdot \vec{z} d\lambda_M(\vec{\varepsilon})d\gamma_M(s)\\
&= \gamma_M(\{1\leq s\leq (1+\delta)^{1/2}\})\int_{S_M}\exp\vec{\varepsilon}\cdot \vec{z} d\lambda_M(\vec{\varepsilon}).
\end{align*}
\end{proof}

\noindent From this lemma and Fubini's theorem, the first term in $(\ref{ASS:main:eq1})$ is bounded from below by 
\begin{align}
\label{ASS:lem5.1:eq1}
\mathbb{E}\log\int_{A_\delta}\left<\exp \vec{\varepsilon}\cdot\vec{z}({\vec{\sigma}})\right>_{M,N}d\lambda_M(\vec{\varepsilon})+\log \nu_M(A_\delta)
\end{align}
Using the standard Gaussian interpolation technique, Lemma $\ref{ASS:lem4}$ below takes care of the second term in $(\ref{ASS:main:eq1})$.

\begin{proof}
Suppose $(y'({\vec{\sigma}}):{\vec{\sigma}}\in S_N)$ is a family of centered Gaussian random variables independent of all the other randomness such that in distribution
\begin{align*}
H_N({\vec{\sigma}})=H_{M,N}({\vec{\sigma}})+\sqrt{M}y'({\vec{\sigma}}).
\end{align*}
It is easy to check that 
$\mathbb{E}y'({\vec{\sigma}}^1)y'({\vec{\sigma}}^2)=\sum_{p\geq 1}\beta_p^2D_pN^pR({\vec{\sigma}}^1,{\vec{\sigma}}^2)^{p}$, where $$
D_{p}=\frac{1}{M}\left(\frac{1}{N^{p-1}}-\frac{1}{(M+N)^{p-1}}\right)
$$ 
satisfies $N^pD_{p}\rightarrow p-1.$ Recall $y({\vec{\sigma}})$ from $(\ref{ASS:eq0.2}).$ Let us consider the interpolating free energy
\begin{align*}
\psi(t)&=\mathbb{E}\log \left<\exp \sqrt{M}\left(\sqrt{t}y'({\vec{\sigma}})+\sqrt{1-t}{y}({\vec{\sigma}})\right)\right>_{M,N}.
\end{align*}
Then $|\psi(1)-\psi(0)|$ gives the quantity in the limit on the left-hand side of $(\ref{ASS:lem4:eq1})$. Thus it suffices to prove that $\psi'(t)\rightarrow 0$ uniformly in $t\in (0,1)$ as $N\rightarrow\infty,$ which can be easily verified by using Gaussian integration by parts, as $N\rightarrow\infty,$
\begin{align*}
\sup_{0<t<1}|\psi'(t)|&\leq M\sup_{{\vec{\sigma}}^1,{\vec{\sigma}}^2\in S_N}|\mathbb{E}y'({\vec{\sigma}}^1)y'({\vec{\sigma}}^2)-\mathbb{E}y({\vec{\sigma}}^1)y({\vec{\sigma}}^2)|\\
&=M\sup_{{\vec{\sigma}}^1,{\vec{\sigma}}^2\in S_N}\left|\sum_{p\geq 1}\beta_p^2(D_{p}N^p-(p-1))R({\vec{\sigma}}^1,{\vec{\sigma}}^2)^p\right|\rightarrow 0.
\end{align*}
\end{proof}


\noindent Let us continue to find a lower bound for the lower limit of the third term in $(\ref{ASS:main:eq1})$. 
It relies on an elementary lemma that allows us to decouple the surface measure $(S_{M+N},\lambda_{M+N})$ as the product measure $(S_N\times A_\delta,\lambda_N\times F_M)$ asymptotically.
For $K\geq 1,$ we denote by $S_K^1$ the unit sphere in $\mathbb{R}^K$ and by $|S_K^1|$ the area of $S_K^1$.
Set
\begin{align*}
A_{M,N}&=\prod_{j=1}^M\left[-\sqrt{M+N+1-j},\sqrt{M+N+1-j}\right],\\
b_{M,N}&=\prod_{j=1}^M\frac{|S_{M+N-j}^1|}{|S_{M+N+1-j}^1|\sqrt{M+N+1-j}}.
\end{align*}
Define
\begin{align*}
F_{M,N}(\vec{\varepsilon})&=b_{M,N}\prod_{j=1}^M\left(1-\frac{\varepsilon_j^2}{M+N+1-j}\right)^{\frac{M+N-j-2}{2}},\quad\vec{\varepsilon}\in A_{M,N},\\
F_M(\vec{\varepsilon})&=\left(\frac{1}{2\pi}\right)^{M/2}\exp\left(-\frac{\|\vec{\varepsilon}\|^2}{2}\right),\quad\vec{\varepsilon}\in \mathbb{R}^M.
\end{align*}
Define $a_1=1$ and for $2\leq \ell\leq M+1,$
$$
a_\ell(\vec{\varepsilon})=\prod_{j=1}^{\ell-1}\sqrt{1+\frac{1-\varepsilon_j^2}{M+N-j}},\quad \vec{\varepsilon}\in A_{M,N}.
$$

\begin{proof}
This is an elementary calculus formula that follows by an induction argument starting from  
\begin{align*}
\int_{S_K}f({\vec{\rho}})d\lambda_K({\vec{\rho}})&=\frac{|S_{K-1}^1|}{|S_K^1|\sqrt{K}}\int_{-\sqrt{K}}^{\sqrt{K}}\left(1-\frac{\varepsilon^2}{K}\right)^{\frac{K-3}{2}}d\varepsilon \int_{S_{K-1}}f\left({\vec{\sigma}} \sqrt{\frac{K-\varepsilon^2}{K-1}},\varepsilon\right)d\lambda_{K-1}({\vec{\sigma}})
\end{align*}
for every $K\geq 2.$
\end{proof}

\noindent As an immediate consequence of Lemma \ref{ASS:lem1}, the cavity coordinates converge weakly to the $M$-dimensional standard Gaussian random vector as $N$ tends to infinity. We write $\mathbb{E}\log {Z_{M+N}}/{\int_{A_\delta}J_{M,N}d\nu_M(\vec{\varepsilon})}$ as
\begin{align}\label{sec2:eq1}
&\mathbb{E}\log \frac{Z_{M+N}}{\int_{A_\delta}F_{M,N}J_{M,N}d\vec{\varepsilon}}+\mathbb{E}\log \frac{\int_{A_\delta}F_{M,N}J_{M,N}d\vec{\varepsilon}}{\int_{A_\delta}F_MJ_{M,N}d\vec{\varepsilon}}.
\end{align}
Then the first term of $(\ref{sec2:eq1})$ can be controlled by the following lemma.

\begin{proof}
Suppose that $(H_{M,N}'({\vec{\sigma}}):{\vec{\sigma}}\in S_N)$ is an independent copy of $(H_{M,N}({\vec{\sigma}}):{\vec{\sigma}}\in S_N)$ and is independent of all the other randomness.
We consider the following interpolating Hamiltonian
\begin{align*}
\varphi(t)=&\mathbb{E}\log\int_{A_\delta}F_{M,N}(\vec{\varepsilon})d\vec{\varepsilon}\int_{S_N}\exp(H_{1,t}({\vec{\rho}})+H_{2,t}({\vec{\rho}})+H_{3,t}({\vec{\rho}}))d
\lambda_N({\vec{\sigma}}),
\end{align*}
where for ${\vec{\rho}}=({\vec{\sigma}},\vec{\varepsilon})$ with ${\vec{\sigma}}\in S_N$ and $\vec{\varepsilon}\in A_\delta,$
\begin{align*}
H_{1,t}({\vec{\rho}})&=\sqrt{t}H_{M,N}({\vec{\sigma}} a_{M+1})+\sqrt{1-t}H_{M,N}'({\vec{\sigma}})\\
H_{2,t}({\vec{\rho}})&=\sum_{i\leq M}\varepsilon_i\left(\sqrt{t}a_i Z_i({\vec{\sigma}} a_{M+1})+\sqrt{1-t}z_i({\vec{\sigma}})\right)\\
H_{3,t}({\vec{\rho}})&=\sqrt{t}\gamma({\vec{\sigma}} a_{M+1},\varepsilon_1a_1,\ldots,\varepsilon_Ma_M).
\end{align*}
From $(\ref{ASS:lem1:eq1})$, obviously $\varphi(1)\leq\mathbb{E}\log Z_{M+N}$ when $N$ is large enough. On the other hand, using Gaussian integration by parts and replicas ${\vec{\rho}}^1=({\vec{\sigma}}^1,\vec{\varepsilon}^1)$ and ${\vec{\rho}}^2=({\vec{\sigma}}^2,\vec{\varepsilon}^2),$ it follows that
\begin{align*}
\varphi'(t)=\frac{1}{2}\sum_{j\leq 3}\left(\mathbb{E}\left<U_{j}({\vec{\rho}},{\vec{\rho}})\right>_t-\mathbb{E}\left<U_j({\vec{\rho}}^1,{\vec{\rho}}^2)\right>_t\right),
\end{align*}
where $\left<\cdot\right>_t$ is the Gibbs average corresponding to random weights $F_{M,N}\exp(H_{1,t}+H_{2,t}+H_{3,t})$ with reference measure
$\lambda_N\times d\vec{\varepsilon}$ on $S_N\times A_\delta$ and
\begin{align*}
U_1({\vec{\rho}}^1,{\vec{\rho}}^2)&=\mathbb{E}H_{M,N}({\vec{\sigma}}^1a_{M+1}(\vec{\varepsilon}^1))H_{M,N}({\vec{\sigma}}^2a_{M+1}(\vec{\varepsilon}^2))-
\mathbb{E}H_{M,N}'({\vec{\sigma}}^1)H_{M,N}'({\vec{\sigma}}^2)\\
U_2({\vec{\rho}}^1,{\vec{\rho}}^2)&=\sum_{i\leq M}\varepsilon_i^1\varepsilon_i^2\left(a_i(\vec{\varepsilon}^1)a_{i}(\vec{\varepsilon}^2)\mathbb{E}Z_i({\vec{\sigma}}^1a_{M+1}(\vec{\varepsilon}^1))Z_i({\vec{\sigma}}^2a_{M+1}(\vec{\varepsilon}^2))
-\mathbb{E}z_i({\vec{\sigma}}^1)z_i({\vec{\sigma}}^2)\right)\\
U_3({\vec{\rho}}^1,{\vec{\rho}}^2)&=\mathbb{E}\gamma({\vec{\sigma}}^1a_{M+1}(\vec{\varepsilon}^1),\eps_1^1a_1(\vec{\varepsilon}^1),\ldots,\eps_M^1a_M(\vec{\varepsilon}^1))\\
&\qquad\cdot\gamma({\vec{\sigma}}^2a_{M+1}(\vec{\varepsilon}^2),\eps_1^2a_1(\vec{\varepsilon}^2),\ldots,\eps_M^2a_M(\vec{\varepsilon}^2)).
\end{align*}
From $(\ref{ASS:eq0.1})$, $(\ref{ASS:eq2.2}),$ and $(\ref{ASS:eq2.3})$, it is easy to see that for $j=2,3,$
$$\lim_{N\rightarrow\infty}\sup_{{\vec{\rho}}^1,{\vec{\rho}}^2\in S_N\times A_\delta}|U_j({\vec{\rho}}^1,{\vec{\rho}}^2)|\rightarrow 0$$
and from $(\ref{ASS:eq2.1})$ and using mean value theorem,
\begin{align*}
&\lim_{N\rightarrow\infty}\sup_{{\vec{\rho}}^1,{\vec{\rho}}^2\in S_N\times A_\delta}|U_1({\vec{\rho}}^1,{\vec{\rho}}^2)|\\
&\leq \lim_{N\rightarrow\infty}\xi'(1)(M+N)\sup_{\vec{\varepsilon}^1,\vec{\varepsilon}^2\in A_\delta}\left|\frac{N}{M+N}a_{M+1}(\vec{\varepsilon}^1)a_{M+1}(\vec{\varepsilon}^2)-1\right|\\
&=\xi'(1)\sup_{\vec{\varepsilon}^1,\vec{\varepsilon}^2\in A_\delta}\left|M-\frac{\|\vec{\varepsilon}^1\|^2+\|\vec{\varepsilon}^2\|^2}{2}\right|\leq M\delta\xi'(1).
\end{align*}
Thus we conclude that $\limsup_{N\rightarrow\infty}\sup_{0<t<1}|\varphi'(t)|\leq M\delta\xi'(1)$ and so $(\ref{ASS:lem2:eq1})$ follows by
\begin{align*}
\liminf_{N\rightarrow\infty}\mathbb{E}\log \frac{Z_{M+N}}{\int_{A_\delta}F_{M,N}J_{M,N}d\vec{\varepsilon}}&\geq \liminf_{N\rightarrow\infty}(\varphi(1)-\varphi(0))\\
&\geq -\limsup_{N\rightarrow\infty}\sup_{0<t<1}|\varphi'(t)|\geq -M\delta\xi'(1).
\end{align*}
\end{proof}

\noindent Finally, let us deal with the second term of $(\ref{sec2:eq1})$ below.
